async function askListWithConfig(
  overrides: {
    session: SessionStore;
    logger?: Logger;
    transport: Record<string, unknown>;
  },
  warningCountAfterStart?: () => number
): Promise<{frames: WireFrame[]; startupWarningCount: number}> {
  const engineConfig = {
    provider: {type: 'mock' as const},
    prompt: {identity: 'Acceptance test.'},
    auth: {ws: async () => ({id: 'u1'})},
    ...overrides,
  };
  const engine = createHalEngine(engineConfig);
  await engine.start(0);
  const startupWarningCount = warningCountAfterStart ? warningCountAfterStart() : 0;
  servers.push(engine);
  const {port} = engine.server.address() as AddressInfo;
  const client = openClient(`ws://127.0.0.1:${port}/hal/ws`);
  const frames = await sendWithBarrier(client, {type: 'list_conversations'}, 11);
  return {frames, startupWarningCount};
}

